const $=id=>document.getElementById(id),key='omni.sitefix.v1';let enabled=[];try{const saved=JSON.parse(localStorage.getItem(key));if(Array.isArray(saved))enabled=saved.filter(id=>OmniSiteFixes.entries.some(e=>e.id===id))}catch{}for(const origin of [...new Set(OmniSiteFixes.entries.map(e=>e.origin))]){const o=document.createElement('option');o.value=origin;o.textContent=new URL(origin).hostname;$('site').append(o)}
function render(){$('cards').replaceChildren();for(const e of OmniSiteFixes.entries.filter(e=>e.origin===$('site').value)){const article=document.createElement('article'),text=document.createElement('div'),h=document.createElement('h2'),p=document.createElement('p'),b=document.createElement('button');h.textContent=e.name;p.textContent='Applies only to '+new URL(e.origin).hostname+'.';text.append(h,p);b.dataset.fixId=e.id;b.textContent=enabled.includes(e.id)?'On':'Off';b.setAttribute('aria-pressed',String(enabled.includes(e.id)));b.setAttribute('aria-label',e.name+' '+b.textContent);b.onclick=()=>{if(enabled.includes(e.id))enabled=enabled.filter(x=>x!==e.id);else enabled.push(e.id);save();render();[...$('cards').querySelectorAll('button')].find(x=>x.dataset.fixId===e.id)?.focus()};article.append(text,b);$('cards').append(article)}}
function save(){try{localStorage.setItem(key,JSON.stringify(enabled));$('status').textContent='Choice saved.'}catch{$('status').textContent='Storage is unavailable. Choice lasts for this visit.'}}$('site').onchange=render;$('reset').onclick=()=>{enabled=enabled.filter(id=>!OmniSiteFixes.entries.some(e=>e.id===id&&e.origin===$('site').value));save();render()};let ps=true;$('glyphs').onclick=()=>{ps=!ps;$('glyphs').textContent=ps?'PlayStation hints':'Xbox hints';$('hints').textContent=ps?'D-pad · Move / Cross · Select / Circle · Back':'D-pad · Move / A · Select / B · Back'};
window.omniPadController=window.omniMediaController=function(a){a=({cross:'confirm',a:'confirm'})[a]||a;const nodes=[...document.querySelectorAll('button,select,input')].filter(e=>!e.disabled&&e.getClientRects().length);let i=nodes.indexOf(document.activeElement);if(['up','down','left','right'].includes(a)){const e=document.activeElement;if(e?.tagName==='SELECT'&&['left','right'].includes(a)){e.selectedIndex=Math.max(0,Math.min(e.options.length-1,e.selectedIndex+(a==='left'?-1:1)));e.dispatchEvent(new Event('change'));return true}nodes[(i+(a==='up'||a==='left'?-1:1)+nodes.length)%nodes.length]?.focus();return true}if(a==='confirm'){document.activeElement?.click();return true}return false};document.addEventListener('keydown',e=>{const a={ArrowUp:'up',ArrowDown:'down',ArrowLeft:'left',ArrowRight:'right'}[e.key];if(a&&omniPadController(a))e.preventDefault()});render();

